'use strict';
Object.assign(iconPaths,{warning:'M12 3 2 21h20L12 3z M12 9v5 M12 17v1',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4'});
workFilters=()=>'';
workCalendar=function(){const events=scheduleEvents(),first=(new Date(calendarYear,calendarMonth,1).getDay()+6)%7,count=new Date(calendarYear,calendarMonth+1,0).getDate(),cells=Math.ceil((first+count)/7)*7;return heading('LỊCH CÔNG VIỆC','Calendar',active?esc(project()?.name||'Dự án'):'Tất cả dự án')+`<div class="month-controls"><button class="btn" data-month="-1" aria-label="Tháng trước">←</button><button class="btn" data-calendar-today>Hôm nay</button><button class="btn" data-month="1" aria-label="Tháng sau">→</button><h2>Tháng ${calendarMonth+1}, ${calendarYear}</h2></div><div class="month-scroll"><div class="month-grid" role="grid" aria-label="Lịch tháng ${calendarMonth+1}/${calendarYear}">${['Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','CN'].map(d=>`<div class="month-weekday" role="columnheader">${d}</div>`).join('')}${Array.from({length:cells},(_,i)=>{const dt=new Date(calendarYear,calendarMonth,i-first+1),day=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0'),items=zenCalendarDayEvents(events,day);return `<section role="gridcell" class="month-cell ${dt.getMonth()!==calendarMonth?'other-month':''} ${day===today()?'today':''}"><time datetime="${day}">${dt.getDate()}</time>${items.map(t=>`<button class="month-event ${t.col==='Done'?'event-done':''}" data-task="${esc(t.id)}" data-pid="${esc(t.project.id)}" style="--event-color:${t.project.color}" title="${esc(t.title)} · ${esc(t.eventStart||'')} → ${esc(t.eventEnd||'')}">${zenCalendarEventTime(t,day)?'<small class="zen-event-time">'+esc(zenCalendarEventTime(t,day))+'</small> ':''}<small class="zen-event-kind">${t.eventLabels?.includes('Hạn hoàn thành')?'Hạn':t.eventLabels?.join(' · ')||(t.eventKind==='deadline'?'Hạn':t.eventKind==='check'?'Checklist':t.eventStart?.slice(0,10)===day?'Bắt đầu':t.eventEnd?.slice(0,10)===day?'Kết thúc':'Đang thực hiện')}</small>${esc(t.title)}</button>`).join('')}</section>`;}).join('')}</div></div><p class="help-copy">Chạm vào công việc để xem chi tiết. Công việc chưa đặt ngày nằm trong Timeline.</p>`;};
let fileAlerts=[],fileCursor=0,fileOwner='',filePolling=false;const localUploads=new Set();
const baseRequestAPI=requestAPI;requestAPI=async function(path,method='GET',body){const result=await baseRequestAPI(path,method,body);if(method==='POST'&&/^assets\/[^/]+\/complete$/.test(path))localUploads.add(path.split('/')[1]);return result;};
function taskNotices(){const now=today(),soon=new Date(Date.parse(now)+3*86400000).toISOString().slice(0,10);return allTasks().filter(t=>t.col!=='Done').flatMap(t=>{const due=t.due||t.end?.slice(0,10)||'',important=['q1','q2'].includes(t.priority)||/quan trọng|ưu tiên/i.test((t.labels||[]).map(l=>l.name).join(' '));const type=due&&due<now?'Quá hạn':due&&due<=soon?'Sắp đến hạn':important?'Quan trọng':'';return type?[{...t,notice:type,due,important}]:[];}).sort((a,b)=>({'Quá hạn':0,'Sắp đến hạn':1,'Quan trọng':2}[a.notice]-{'Quá hạn':0,'Sắp đến hạn':1,'Quan trọng':2}[b.notice]));}
const bell=document.createElement('button');bell.id='notifications-button';bell.className='icon-btn notification-bell';bell.type='button';bell.setAttribute('aria-label','Thông báo');document.querySelector('.top-actions').insertBefore(bell,document.querySelector('.top-actions>.avatar'));
function refreshBell(){const count=taskNotices().length+fileAlerts.length;bell.innerHTML=svgIcon('bell')+(count?'<span class="notification-count">'+(count>99?'99+':count)+'</span>':'');bell.setAttribute('aria-label','Thông báo · '+count+' mục');}
bell.onclick=()=>{const tasks=taskNotices();modal('<h2>Thông báo</h2><p class="help-copy">Công việc đang hoạt động · đến hạn trong 3 ngày · tệp mới từ thiết bị khác.</p><div class="notice-list">'+tasks.map(t=>`<button class="notice-item" data-task="${esc(t.id)}" data-pid="${esc(t.project.id)}"><strong>${esc(t.notice)}${t.important&&t.notice!=='Quan trọng'?' · Quan trọng':''}</strong><span>${esc(t.title)}</span><small>${esc(t.project.name)}${t.due?' · '+esc(t.due.split('-').reverse().join('/')):''}</small><span class="notice-detail-link">Xem chi tiết →</span></button>`).join('')+fileAlerts.map(f=>`<a class="notice-item" href="/api/assets/${esc(f.id)}"><strong>Tệp mới từ thiết bị khác</strong><span>${esc(f.name)}</span></a>`).join('')+(!tasks.length&&!fileAlerts.length?'<p>Chưa có thông báo.</p>':'')+'</div><button class="btn" type="button" id="clear-file-alerts">Đã xem thông báo tệp</button>',null,true);$('#clear-file-alerts').onclick=()=>{fileAlerts=[];refreshBell();$('#editor').close();};};
async function pollFileUpdates(){if(document.hidden||!currentUser||!navigator.onLine||filePolling)return;if(fileOwner!==currentUser.id){fileOwner=currentUser.id;fileCursor=Date.now();fileAlerts=[];localUploads.clear();}filePolling=true;try{const result=await requestAPI('file-updates?since='+fileCursor);for(const f of result.files)if(!localUploads.has(f.id)&&!fileAlerts.some(a=>a.id===f.id))fileAlerts.unshift(f);fileAlerts=fileAlerts.slice(0,50);fileCursor=result.cursor;refreshBell();}catch{}finally{filePolling=false;}}
const beforeUXRender=render;render=function(){beforeUXRender();if(currentUser&&fileOwner!==currentUser.id){fileOwner=currentUser.id;fileCursor=Date.now();fileAlerts=[];localUploads.clear();}refreshBell();};
document.addEventListener('click',e=>{if(e.target.closest('[data-calendar-today]')){const now=new Date();calendarMonth=now.getMonth();calendarYear=now.getFullYear();render();}});
setInterval(()=>{refreshBell();pollFileUpdates();},60000);window.addEventListener('focus',pollFileUpdates);window.addEventListener('online',pollFileUpdates);refreshBell();


// Merge a task's deadline with its execution entry only when both occur on this day.
function zenCalendarEventTime(event,day){for(const value of [event.eventStart,event.eventEnd])if(typeof value==='string'&&value.slice(0,10)===day&&value.includes('T'))return value.slice(11,16);return '';}
function zenCalendarDayEvents(events,day){const matches=events.filter(t=>t.eventStart?.slice(0,10)<=day&&t.eventEnd?.slice(0,10)>=day),result=[],byTask=new Map();for(const event of matches){if(event.eventKind==='check'){result.push(event);continue;}const key=event.project.id+'\0'+event.id;let item=byTask.get(key);if(!item){item={...event,eventLabels:[]};byTask.set(key,item);result.push(item);}if(event.eventKind==='deadline'){item.eventLabels.push('Hạn hoàn thành');if(event.title.startsWith('Hạn: '))item.title=event.title.slice(5);}else{if(event.eventStart?.slice(0,10)===day)item.eventLabels.push('Bắt đầu');if(event.eventEnd?.slice(0,10)===day)item.eventLabels.push('Kết thúc');if(!item.eventLabels.length)item.eventLabels.push('Đang thực hiện');item.eventStart=event.eventStart;item.eventEnd=event.eventEnd;item.title=event.title;}}for(const item of result)if(item.eventLabels?.includes('Hạn hoàn thành'))item.eventLabels=item.eventLabels.filter(label=>label!=='Kết thúc');return result;}
